{
  "html": "<!doctype html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Forest Temple Level 2 – Fireboy & Watergirl</title>
<style>
  body,html{margin:0;padding:0;overflow:hidden;background:#222;font-family:Arial,Helvetica,sans-serif;}
  #hud{position:absolute;top:5px;left:5px;color:#fff;z-index:10;}
  #hud div{margin:2px 0;}
  #restartBtn{position:absolute;top:5px;right:5px;padding:5px 10px;background:#555;color:#fff;border:none;cursor:pointer;z-index:10;}
  canvas{background:#111;display:block;}
</style>
</head>
<body>
<div id="hud">
  <div id="timer">Time: 0.0 s</div>
  <div id="fireDiamonds">Fireboy Diamonds: 0 / 8</div>
  <div id="waterDiamonds">Watergirl Diamonds: 0 / 8</div>
  <div id="status"></div>
</div>
<button id="restartBtn">Restart (R)</button>
<canvas id="game" width="1280" height="960"></canvas>
<script>
(()=>{
  const canvas=document.getElementById('game');
  const ctx=canvas.getContext('2d');
  const TILE=32;
  const MAP_ROWS=29, MAP_COLS=39;
  const mapRows=[
    "111111111111111111111111111111111111111",
    "100000000000000000000000000000000000001",
    "100000000000000000000000000000000000001",
    "100000000000000000000000000000000000001",
    "100000000000000000000000000000000000001",
    "111111111111111110000011111111300000001",
    "100000000000000000000000000011130000001",
    "100000000000000000000000000001111000001",
    "100000000000000000000000000000000000001",
    "100000000000000000000000000000000001111",
    "100000000000000000000000000000000001111",
    "100000000000000000000000000000000001111",
    "100000000000000000000000000000000111111",
    "100000000000000000000000000000000111111",
    "100000000000000001111110000000000111111",
    "100000118888888881111118888888111111111",
    "100000000000000000000000000000000000001",
    "111100000000000000000000000000000000001",
    "111100000000000000000000000000000000001",
    "111100000000000000000000000000000000001",
    "111111111111111111111111111111111130001",
    "100000000000000000000000000000000000001",
    "100000000000000000000000000000000000001",
    "100000000000000000000000000000000000001",
    "100000000000000000000000000000000000211",
    "100000666666666000000077777777700002111",
    "100000000000000000000000000000000001111",
    "100000000000000000000000000000000001111",
    "111111777777777111111166666666611111111"
  ];
  // Mapping gid to colors / types
  const gidInfo={
    '0':{type:'empty'},
    '1':{type:'solid',color:'#555'},
    '2':{type:'solid',color:'#555'}, // slope up right treated as solid
    '3':{type:'solid',color:'#555'}, // slope down right treated as solid
    '6':{type:'blue',color:'#00f'},
    '7':{type:'red',color:'#c00'},
    '8':{type:'green',color:'#0a0'}
  };

  // Helper to draw a tile
  function drawTile(gid,x,y){
    const info=gidInfo[gid];
    if(!info||info.type==='empty')return;
    ctx.fillStyle=info.color;
    ctx.fillRect(x,y,TILE,TILE);
  }

  // Game objects
  const spawns={fireboy:{x:72,y:864},watergirl:{x:152,y:864}};
  const exits={
    fireboy:{x:96,y:160,w:64,h:64},
    watergirl:{x:208,y:160,w:64,h:64}
  };
  const diamonds={
    red:[ [920,592],[496,592],[592,120],[608,392],[272,864],[408,864],[776,768],[920,768] ],
    blue:[ [656,120],[672,392],[336,592],[264,768],[408,768],[776,864],[920,864],[776,592] ]
  };
  const pools=[
    {color:'blue',rect:[192,800,288,32]},
    {color:'red',rect:[704,800,288,32]},
    {color:'red',rect:[192,896,288,32]},
    {color:'blue',rect:[704,896,288,32]},
    {color:'green',rect:[416,480,288,32]},
    {color:'green',rect:[896,480,224,32]}
  ];
  const pressurePlates=[
    {id:'lower-left',x:192-16,y:640-16,w:32,h:32,group:0},
    {id:'lower-right',x:1040-16,y:640-16,w:32,h:32,group:0},
    {id:'upper-left',x:320-16,y:160-16,w:32,h:32,group:2},
    {id:'upper-right',x:912-16,y:160-16,w:32,h:32,group:2}
  ];
  const movingObjects={
    barrier:{x:624,y:512,w:32,h:128,restY:512,pressedY:384,group:0},
    bridge:{x:704,y:160,w:160,h:32,restX:704,pressedX:544,group:2}
  };
  const hangingBoards=[
    {id:'first',anchorX:384,anchorY:264,centerX:384,centerY:408,width:102,thick:8,angle:0},
    {id:'second',anchorX:864,anchorY:264,centerX:864,centerY:424,width:102,thick:8,angle:0}
  ];

  // Characters
  class Player{
    constructor(name,color,keys){
      this.name=name;this.color=color;this.keys=keys; // key mapping {left,right,up}
      this.width=20;this.height=40; // Approx size
      this.reset();
    }
    reset(){
      const spawn=spawns[this.name];
      this.x=spawn.x;this.y=spawn.y;
      this.vx=0;this.vy=0;this.onGround=false;this.alive=true;this.collect=0;
    }
    update(dt){
      if(!this.alive)return;
      // Horizontal movement
      const speed=2.5;
      if(this.keys.left){ this.vx=-speed; }
      else if(this.keys.right){ this.vx= speed; }
      else { this.vx=0; }
      // Jump
      if(this.keys.up && this.onGround){ this.vy=-12; this.onGround=false; }
      // Apply gravity
      const gravity=0.5;
      this.vy+=gravity;
      // Apply velocities
      this.x+=this.vx;
      this.handleCollisions('x');
      this.y+=this.vy;
      this.handleCollisions('y');
      // Death check
      this.checkHazards();
    }
    handleCollisions(axis){
      // Determine tiles overlapped by bounding box
      const minX=Math.floor(this.x/TILE), maxX=Math.floor((this.x+this.width)/TILE);
      const minY=Math.floor(this.y/TILE), maxY=Math.floor((this.y+this.height)/TILE);
      // include moving objects as solid
      const solids=[];
      // Add static solid tiles from map
      for(let row=minY; row<=maxY; row++){
        if(row<0||row>=MAP_ROWS) continue;
        const line=mapRows[row];
        for(let col=minX; col<=maxX; col++){
          if(col<0||col>=MAP_COLS) continue;
          const gid=line[col];
          if(gid==='1'||gid==='2'||gid==='3') solids.push({x:col*TILE,y:row*TILE,w:TILE,h:TILE});
        }
      }
      // Add moving barrier and bridge as solids
      const barrier=movingObjects.barrier;
      solids.push({x:barrier.x,y:barrier.y,w:barrier.w,h:barrier.h});
      const bridge=movingObjects.bridge;
      solids.push({x:bridge.x,y:bridge.y,w:bridge.w,h:bridge.h});
      // Add hanging boards (treated as solid rectangles rotated)
      for(const board of hangingBoards){
        // For simplicity, treat as axis-aligned bounding box of rotated board
        const rad=board.angle;
        const w=board.width, h=board.thick;
        // compute corners to get AABB
        const cx=board.centerX, cy=board.centerY;
        const cos=Math.cos(rad), sin=Math.sin(rad);
        const hw=w/2, hh=h/2;
        const pts=[
          {x:-hw, y:-hh},
          {x: hw, y:-hh},
          {x: hw, y: hh},
          {x:-hw, y: hh}
        ];
        let minAx=Infinity, maxAx=-Infinity, minAy=Infinity, maxAy=-Infinity;
        for(const p of pts){
          const rx=cx + p.x*cos - p.y*sin;
          const ry=cy + p.x*sin + p.y*cos;
          if(rx<minAx)minAx=rx; if(rx>maxAx)maxAx=rx;
          if(ry<minAy)minAy=ry; if(ry>maxAy)maxAy=ry;
        }
        solids.push({x:minAx,y:minAy,w:maxAx-minAx,h:maxAy-minAy});
      }
      // Collision resolution
      for(const s of solids){
        if(this.x+this.width> s.x && this.x < s.x+s.w && this.y+this.height> s.y && this.y < s.y+s.h){
          if(axis==='x'){
            if(this.vx>0){ this.x = s.x - this.width - 0.01; }
            else if(this.vx<0){ this.x = s.x + s.w + 0.01; }
            this.vx=0;
          }else if(axis==='y'){
            if(this.vy>0){ // falling
              this.y = s.y - this.height - 0.01;
              this.onGround=true; this.vy=0;
            }else if(this.vy<0){ // rising
              this.y = s.y + s.h + 0.01;
              this.vy=0;
            }
          }
        }
      }
    }
    checkHazards(){
      // Pools are rectangles; detect overlapping
      for(const p of pools){
        const [rx,ry,rw,rh]=p.rect;
        if(this.x+this.width>rx && this.x<rx+rw && this.y+this.height>ry && this.y<ry+rh){
          // Determine if this pool is fatal for this character
          if(p.color==='green') { this.die('green'); return; }
          if(p.color==='blue' && this.name==='fireboy'){ this.die('blue'); return; }
          if(p.color==='red' && this.name==='watergirl'){ this.die('red'); return; }
          // otherwise safe (matching element)
        }
      }
    }
    die(reason){
      this.alive=false;
      this.vx=this.vy=0;
    }
    draw(){
      if(!this.alive)return;
      ctx.fillStyle=this.color;
      ctx.fillRect(this.x,this.y,this.width,this.height);
    }
  }

  const fireboy=new Player('fireboy','#c33', {left:false,right:false,up:false});
  const watergirl=new Player('watergirl','#3c3', {left:false,right:false,up:false});

  // Input handling
  const keyMap={
    ArrowLeft:{player:fireboy, prop:'left'},
    ArrowRight:{player:fireboy, prop:'right'},
    ArrowUp:{player:fireboy, prop:'up'},
    a:{player:watergirl, prop:'left'},
    d:{player:watergirl, prop:'right'},
    w:{player:watergirl, prop:'up'}
  };
  window.addEventListener('keydown',e=>{
    if(e.key==='r' || e.key==='R') { restart(); e.preventDefault(); return; }
    const mapping=keyMap[e.key];
    if(mapping){
      mapping.player.keys[mapping.prop]=true;
      e.preventDefault();
    }
  });
  window.addEventListener('keyup',e=>{
    const mapping=keyMap[e.key];
    if(mapping){
      mapping.player.keys[mapping.prop]=false;
      e.preventDefault();
    }
  });

  // Game state
  let elapsed=0; let timerId=null; let gameOver=false; let victory=false;
  const collected={red:[],blue:[]};

  function restart(){
    fireboy.reset(); watergirl.reset();
    elapsed=0; gameOver=false; victory=false;
    collected.red=[]; collected.blue=[];
    // Reset moving objects
    movingObjects.barrier.y=movingObjects.barrier.restY;
    movingObjects.bridge.x=movingObjects.bridge.restX;
    // Reset hanging boards angle and position
    hangingBoards[0].angle=0; hangingBoards[0].centerY=408; // initial positions
    hangingBoards[1].angle=0; hangingBoards[1].centerY=424;
    // Reset UI
    document.getElementById('status').textContent='';
    updateHUD();
    if(timerId) clearInterval(timerId);
    timerId=setInterval(()=>{ elapsed+=0.1; updateHUD(); },100);
  }

  function updateHUD(){
    document.getElementById('timer').textContent='Time: '+elapsed.toFixed(1)+' s';
    document.getElementById('fireDiamonds').textContent='Fireboy Diamonds: '+collected.red.length+' / 8';
    document.getElementById('waterDiamonds').textContent='Watergirl Diamonds: '+collected.blue.length+' / 8';
  }

  function checkPlateActivation(){
    // Lower plates control barrier
    const lowerActive=pressurePlates.slice(0,2).some(p=>isPlayerOnPlate(p));
    const barrier=movingObjects.barrier;
    if(lowerActive){ barrier.y=barrier.pressedY; }
    else { barrier.y=barrier.restY; }
    // Upper plates control bridge
    const upperActive=pressurePlates.slice(2).some(p=>isPlayerOnPlate(p));
    const bridge=movingObjects.bridge;
    if(upperActive){ bridge.x=bridge.pressedX; }
    else { bridge.x=bridge.restX; }
  }

  function isPlayerOnPlate(plate){
    const p=plate;
    const plRect={x:p.x,y:p.y,w:p.w,h:p.h};
    const f={x:fireboy.x,y:fireboy.y,w:fireboy.width,h:fireboy.height};
    const w={x:watergirl.x,y:watergirl.y,w:watergirl.width,h:watergirl.height};
    function overlap(a,b){return a.x<a.x+b.w && a.x+a.w>b.x && a.y<a.y+b.h && a.y+a.h>b.y;}
    return overlap(f,plRect)||overlap(w,plRect);
  }

  function updateHangingBoards(){
    // Simple tilt based on which player is standing near the center of the board
    for(const board of hangingBoards){
      // Reset angle each frame, then compute if a player is near
      board.angle=0;
      const left=board.centerX- board.width/2;
      const right=board.centerX+ board.width/2;
      const top=board.centerY - board.thick/2;
      const bottom=board.centerY + board.thick/2;
      const players=[fireboy,watergirl];
      for(const p of players){
        if(!p.alive)continue;
        // simple check: vertical distance small and horizontal within board width
        const px=p.x + p.width/2;
        const py=p.y + p.height;
        if(px>left && px<right && Math.abs(py - board.centerY)<20){
          const offset=(px - board.centerX)/(board.width/2); // -1..1
          const maxAngle=0.25; // radians (~14deg)
          board.angle=offset*maxAngle;
          // keep player on surface (approximate by moving y to board surface)
          p.y=board.centerY - p.height - 1;
        }
      }
    }
  }

  function checkDiamondPickup(){
    // Red diamonds for fireboy
    for(let i=diamonds.red.length-1;i>=0;i--){
      const [dx,dy]=diamonds.red[i];
      if(pointInRect(fireboy.x+fireboy.width/2, fireboy.y+fireboy.height/2, dx-8, dy-8,16,16)){
        collected.red.push(i);
        diamonds.red.splice(i,1);
      }
    }
    // Blue diamonds for watergirl
    for(let i=diamonds.blue.length-1;i>=0;i--){
      const [dx,dy]=diamonds.blue[i];
      if(pointInRect(watergirl.x+watergirl.width/2, watergirl.y+watergirl.height/2, dx-8, dy-8,16,16)){
        collected.blue.push(i);
        diamonds.blue.splice(i,1);
      }
    }
  }

  function pointInRect(px,py,x,y,w,h){
    return px>=x && px<=x+w && py>=y && py<=y+h;
  }

  function checkVictory(){
    if(!fireboy.alive || !watergirl.alive) return;
    const fExit=exits.fireboy; const wExit=exits.watergirl;
    const fInside=pointInRect(fireboy.x+fireboy.width/2, fireboy.y+fireboy.height/2, fExit.x, fExit.y, fExit.w, fExit.h);
    const wInside=pointInRect(watergirl.x+watergirl.width/2, watergirl.y+watergirl.height/2, wExit.x, wExit.y, wExit.w, wExit.h);
    if(fInside && wInside){ victory=true; gameOver=true; document.getElementById('status').textContent='Victory!'; }
  }

  function drawMap(){
    for(let row=0; row<MAP_ROWS; row++){
      const line=mapRows[row];
      for(let col=0; col<MAP_COLS; col++){
        const gid=line[col];
        drawTile(gid, col*TILE, row*TILE);
      }
    }
    // Draw pools overlay (semi-transparent)
    for(const p of pools){
      const [rx,ry,rw,rh]=p.rect;
      ctx.fillStyle=(p.color==='blue')?'rgba(0,0,255,0.4)':(p.color==='red')?'rgba(255,0,0,0.4)':'rgba(0,255,0,0.4)';
      ctx.fillRect(rx,ry,rw,rh);
    }
    // Draw diamonds
    for(const d of diamonds.red){
      ctx.fillStyle='red';
      ctx.beginPath();ctx.arc(d[0],d[1],8,0,Math.PI*2);ctx.fill();
    }
    for(const d of diamonds.blue){
      ctx.fillStyle='cyan';
      ctx.beginPath();ctx.arc(d[0],d[1],8,0,Math.PI*2);ctx.fill();
    }
    // Draw exits
    ctx.fillStyle='rgba(255,0,0,0.5)';
    ctx.fillRect(exits.fireboy.x,exits.fireboy.y,exits.fireboy.w,exits.fireboy.h);
    ctx.fillStyle='rgba(0,0,255,0.5)';
    ctx.fillRect(exits.watergirl.x,exits.watergirl.y,exits.watergirl.w,exits.watergirl.h);
    // Draw pressure plates
    for(const plate of pressurePlates){
      ctx.fillStyle='gray';
      ctx.fillRect(plate.x,plate.y,plate.w,plate.h);
    }
    // Draw moving barrier and bridge
    const barrier=movingObjects.barrier;
    ctx.fillStyle='brown';
    ctx.fillRect(barrier.x,barrier.y,barrier.w,barrier.h);
    const bridge=movingObjects.bridge;
    ctx.fillStyle='brown';
    ctx.fillRect(bridge.x,bridge.y,bridge.w,bridge.h);
    // Draw hanging boards (rope + plank)
    ctx.strokeStyle='white';
    ctx.lineWidth=2;
    for(const board of hangingBoards){
      // rope
      ctx.beginPath();
      ctx.moveTo(board.anchorX, board.anchorY);
      ctx.lineTo(board.centerX, board.centerY);
      ctx.stroke();
      // plank (rotated rectangle)
      ctx.save();
      ctx.translate(board.centerX, board.centerY);
      ctx.rotate(board.angle);
      ctx.fillStyle='saddlebrown';
      ctx.fillRect(-board.width/2, -board.thick/2, board.width, board.thick);
      ctx.restore();
    }
  }

  function gameLoop(){
    if(gameOver) return;
    ctx.clearRect(0,0,canvas.width,canvas.height);
    // Update physics
    fireboy.update(16);
    watergirl.update(16);
    // plates affect moving objects
    checkPlateActivation();
    // hanging boards tilt/respond
    updateHangingBoards();
    // diamond pickup
    checkDiamondPickup();
    // Victory check
    checkVictory();
    // Draw everything
    drawMap();
    fireboy.draw();
    watergirl.draw();
    // Death feedback
    if(!fireboy.alive || !watergirl.alive){
      document.getElementById('status').textContent='Game Over';
      gameOver=true;
    }
    requestAnimationFrame(gameLoop);
  }

  document.getElementById('restartBtn').addEventListener('click',restart);
  // Prevent arrow keys from scrolling
  window.addEventListener('keydown',e=>{ if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space'].includes(e.key)) e.preventDefault(); });

  restart();
  requestAnimationFrame(gameLoop);
})();
</script>
</body>
</html>"
}
